css:
:root{color-scheme:dark;--ink:#fbf8f2;--muted:#93a6b5;--gold:#ceaa6a;--orange:#ceaa6a;--line:#ffffff17;--panel:#18140c}
*{box-sizing:border-box}html,body{margin:0;height:100%;overflow:hidden}
body{background:#0b0a06;color:var(--ink);font-family:Arial,Helvetica,sans-serif}
button,a{-webkit-tap-highlight-color:transparent}button{font:inherit;color:inherit;cursor:pointer;border:0;background:none}
button:focus-visible,a:focus-visible{outline:2px solid var(--orange);outline-offset:4px}button:disabled{opacity:.35;cursor:not-allowed}button:hover:not(:disabled){filter:brightness(1.2)}
#scene{position:fixed;left:0;right:0;top:94px;bottom:132px;touch-action:none}#scene canvas{display:block;width:100%;height:100%}
.vignette{position:fixed;inset:0;pointer-events:none;background:linear-gradient(90deg,#0b0a06ee,#0b0a06b0 20%,transparent 34%,transparent 70%,#0b0a06b0 82%,#0b0a06ee)}
header{position:fixed;top:0;left:0;right:0;height:94px;padding:0 4%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);z-index:3;background:#0b0a06}
.brand{font-size:15px;font-weight:700;letter-spacing:3px;text-decoration:none;color:inherit;display:flex;align-items:center;gap:15px}.brandmark{font-size:29px;font-weight:900;color:var(--orange);font-style:italic}.arcade{font-weight:400;font-size:11px;letter-spacing:2px;color:#bab19d;margin-left:12px}
.top-right{display:flex;align-items:center;gap:14px}.pill{border:1px solid #7f643160;border-radius:30px;padding:8px 13px;font-size:10px;letter-spacing:1.4px;color:#e7d6b7}
.pill i,.live-dot{display:inline-block;border-radius:50%;background:#ceaa6a;width:5px;height:5px;margin-right:7px;vertical-align:middle}
.icon{font-size:19px;width:36px;height:36px;color:#ece3d1;border:1px solid #ffffff18;border-radius:50%}
#viewbar{position:fixed;top:108px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:3px;padding:4px;border:1px solid #ffffff16;border-radius:30px;background:#16130bc8;z-index:2;white-space:nowrap}
.view-btn{font-size:12px;color:#c8bfaa;border-radius:20px;padding:8px 14px}.view-btn.active{background:#efe5cf1f;color:#faf6ee}#viewHint{font-size:10px;color:#7f95a5;letter-spacing:1px;margin:0 12px}
main{position:fixed;inset:94px 0 132px;pointer-events:none;z-index:1}
.intro{position:absolute;left:4%;top:7%;width:255px;pointer-events:auto;transition:opacity .3s}
.eyebrow{font-size:10px;letter-spacing:2px;color:#bab19d;font-weight:600;line-height:1.8;margin:0}
h1{font-size:clamp(35px,4.1vw,64px);line-height:.98;letter-spacing:-2.6px;font-weight:500;margin:22px 0;color:#fbf8f2}h1 em{font-family:Georgia,serif;font-weight:400;color:var(--gold)}
.tagline{font-family:Georgia,serif;font-size:17px;line-height:1.55;color:#d5cdbb}
.edition{font-size:10px;letter-spacing:2px;color:#d8ba86;margin:24px 0 28px;display:flex;align-items:center;gap:9px}.edition span{width:22px;height:1px;background:#c8a056}
.feature-list{border-top:1px solid var(--line)}.feature-list button{display:flex;width:100%;align-items:center;text-align:left;border-bottom:1px solid var(--line);padding:14px 0;gap:13px}
.feature-list b{font-size:10px;color:#d5b67f;font-weight:400}.feature-list span{font-size:13px}.feature-list small{display:block;color:#8ea3b2;font-size:11px;margin-top:6px}.feature-list i{font-style:normal;font-size:14px;color:#7e93a2;margin-left:auto}
.text-button{padding:0;font-size:11px;letter-spacing:.3px;color:#cdc4b0}.intro>.text-button{margin-top:20px}
.session{position:absolute;right:4%;top:12%;width:178px;pointer-events:auto;transition:opacity .3s}.session>.eyebrow{margin-bottom:18px}
.session-row{display:flex;justify-content:space-between;font-size:12px;margin:14px 0;color:#93a6b5}.session-row b{font-weight:400;color:#f3ecde;font-variant-numeric:tabular-nums}
.session-rule{height:1px;background:var(--line);margin:22px 0}.meter{font:28px Georgia,serif;color:var(--gold);margin:8px 0 20px;font-variant-numeric:tabular-nums}
.layr-note{font-family:Georgia,serif;font-size:13px;line-height:1.7;color:#c8bfab}.session .text-button{margin-top:10px}
body.close-view .intro,body.close-view .session{opacity:0;pointer-events:none}
.machine-caption{position:absolute;bottom:10px;left:25%;width:50%;text-align:center;font-size:11px;letter-spacing:1.6px;color:#e7d6b7;line-height:1.6;transition:opacity .2s}
body.feature-on .machine-caption{opacity:0}
#featureBar{position:fixed;left:50%;bottom:146px;transform:translateX(-50%);z-index:4;background:#18140cf4;border:1px solid #ceaa6a66;border-radius:12px;padding:14px 18px;display:flex;gap:20px;align-items:center;max-width:94vw;box-shadow:0 20px 60px #000a;backdrop-filter:blur(10px)}
#featureBar[hidden]{display:none}.fb-head{display:flex;flex-direction:column;gap:4px;min-width:170px}.fb-head strong{font:22px Georgia,serif;color:#dcc092;font-weight:400}.fb-head span:last-child{font-size:12px;color:#d1c8b5}
#fbBody{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.pick{width:40px;height:40px;border:1px solid #c8a05690;border-radius:7px;color:#f2e8d6;background:#2d2410;font-size:13px;font-weight:700}.pick.picked{background:#ceaa6a33;border-color:#e0c79e;color:#ffffff}
.bar-cta{background:linear-gradient(120deg,#e0c79e,#c29541);color:#191308;padding:12px 18px;border-radius:6px;font-weight:700;font-size:12px;letter-spacing:1px;box-shadow:0 3px 0 #695122}
.console{position:fixed;bottom:0;left:0;right:0;min-height:132px;background:#16130bf2;border-top:1px solid #ceaa6a2e;display:flex;align-items:center;padding:20px 4%;gap:3.2%;backdrop-filter:blur(18px);z-index:3}
.console label{display:block;font-size:10px;letter-spacing:1.4px;color:#bab19d;margin-bottom:9px}.console strong{font-size:29px;font-weight:400;letter-spacing:-.8px;font-variant-numeric:tabular-nums}.console small{font-size:10px;letter-spacing:1px;color:#b4ab96;margin-left:8px}
.credit{min-width:160px}.credit label button{border:1px solid #8e7a5270;margin-left:8px;width:20px;height:20px;border-radius:50%;font-size:13px;padding:0;line-height:1}
.bet{border-left:1px solid var(--line);padding-left:3.2%;min-width:170px}.bet label span{font-size:9px;color:#6f8796;margin-left:8px}
.stepper{display:flex;align-items:center;gap:18px}.stepper strong{font-size:23px;min-width:45px;text-align:center}.stepper button{border:1px solid #816d4466;border-radius:50%;width:30px;height:30px;color:#f3ebda;font-size:16px}
.last{min-width:150px;border-left:1px solid var(--line);padding-left:3.2%}.last strong{color:#dcc092}
.gamble-btn{display:block;margin-top:6px;padding:5px 10px;border:1px solid #c8a056;border-radius:4px;color:#f2e8d6;background:#352911;font-size:10px;letter-spacing:1px;font-weight:700;animation:pulse 1.4s ease-in-out infinite}.gamble-btn[hidden]{display:none}
.actions{display:flex;gap:10px;margin-left:auto;align-items:center}
.secondary{height:54px;border:1px solid #8e7a5260;border-radius:5px;font-size:10px;letter-spacing:1px;width:72px;color:#f3ebdb}.secondary[aria-pressed=true]{border-color:#ceaa6a;color:#eee0c9;background:#ceaa6a14}
.spin{background:linear-gradient(120deg,#e0c79e,#c29541);color:#191308;width:170px;height:63px;border-radius:6px;box-shadow:0 4px 0 #695122,0 0 35px #c2954114;font-size:14px;letter-spacing:2px;font-weight:700;display:flex;align-items:center;justify-content:center;gap:24px}
.spin .spin-icon{font-size:26px;font-weight:400}.spin:active{transform:translateY(3px);box-shadow:0 1px 0 #695122}.spin.spinning .spin-icon{animation:rotate .7s linear infinite}.spin.small{font-size:12px;letter-spacing:1px}
.utility{display:flex;flex-direction:column;gap:13px}.utility button{font-size:10px;letter-spacing:.7px;color:#c3baa5;text-align:left;white-space:nowrap}
#toast{position:fixed;bottom:160px;left:50%;transform:translate(-50%,15px);opacity:0;background:#ceaa6a;color:#191308;border-radius:6px;padding:13px 20px;font-size:13px;pointer-events:none;transition:.2s;z-index:12;max-width:90vw;text-align:center}#toast.show{opacity:1;transform:translate(-50%,0)}
#celebration{position:fixed;inset:0;pointer-events:none;overflow:hidden;z-index:5}.coin{position:absolute;width:14px;height:14px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#f2e7d6,#b68b3b 70%);border:2px solid #efe3cf;animation:fall 2.4s ease-in both;box-shadow:0 0 12px #ceaa6a40}
dialog{border:1px solid #6a542a66;background:var(--panel);color:#f7f1e5;border-radius:15px;width:min(720px,94vw);max-height:86vh;padding:26px 28px;box-shadow:0 35px 120px #000a}dialog::backdrop{background:#080602c9;backdrop-filter:blur(10px)}
.modal-head{display:flex;align-items:center;justify-content:space-between}.modal-head button{font-size:28px;color:#c1b8a3}
dialog h2{font:34px Georgia,serif;color:#dcc092;margin:16px 0;font-weight:400}dialog p,dialog li{font-size:13px;color:#d2cab8;line-height:1.75}dialog h3{font-size:12px;letter-spacing:1.5px;color:#f2e9d7;margin-top:26px}
.cta{background:#ceaa6a;color:#191308;padding:13px 20px;border-radius:6px;font-weight:700;font-size:12px;margin:12px 8px 0 0;display:inline-block}.outline{border:1px solid #816d4485;padding:12px 18px;border-radius:5px;font-size:12px;margin:8px 8px 0 0;display:inline-block}
.paytable{width:100%;border-collapse:collapse;font-size:12px}.paytable th{color:#b4ab96;font-weight:400;font-size:10px;text-align:left;letter-spacing:1px}.paytable td,.paytable th{padding:9px;border-bottom:1px solid #ffffff12}
.pay-icon{width:30px;height:30px;vertical-align:middle;margin-right:8px}
.rule-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.line-card{border:1px solid #ffffff14;padding:8px;text-align:center;font-size:10px;color:#8aa1b0;border-radius:4px}.line-card svg{width:100%;height:32px}
.bonus-total{font-size:40px;color:#dcc092;font-family:Georgia,serif;margin:12px 0}
.lab-options{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.lab-options button{border:1px solid #c8a05660;border-radius:8px;padding:22px 10px;color:#f2e8d6;font-size:13px}.lab-options small{display:block;font-size:11px;color:#b4ab96;margin-top:8px}
.stat-cards{display:flex;gap:10px;margin:18px 0}.stat-cards>div{padding:14px;border:1px solid #ffffff16;border-radius:8px;flex:1}.stat-cards span{display:block;font-size:11px;color:#c8bfac}.stat-cards strong{display:block;font-size:22px;margin-top:8px;font-weight:400;color:#dcc092}
.setting{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:15px 0;border-bottom:1px solid #ffffff15;font-size:13px}.setting input[type=range]{width:45%;accent-color:#ceaa6a}.setting input[type=checkbox]{accent-color:#ceaa6a;width:18px;height:18px}
.setting select{background:#171309;color:#f8f3e9;border:1px solid #635230;border-radius:6px;padding:7px 10px;font:inherit;font-size:13px}
.history-wrap{max-height:330px;overflow:auto}.fine{font-size:11px!important;color:#8ba1b0!important}
.hash{font:12px/1.6 ui-monospace,Menlo,Consolas,monospace;word-break:break-all;color:#f6f1e5;background:#0f0d07;border:1px solid #ffffff14;border-radius:6px;padding:12px}.hash b{color:#d8b986;font-size:16px}
.ticket{background:#ebe3cc;color:#262622;padding:24px;text-align:center;border-radius:5px;margin:14px 0}.ticket h4{font:40px Georgia,serif;margin:10px 0}.ticket p{color:#5f5a4e!important;font-size:11px!important;margin:6px 0}.barcode{height:34px;background:repeating-linear-gradient(90deg,#222 0 2px,transparent 2px 5px,#222 5px 6px,transparent 6px 9px);margin-top:12px}
#loading{position:fixed;inset:0;background:#0b0a06;z-index:50;display:flex;align-items:center;justify-content:center;flex-direction:column;transition:opacity .5s}.loader-mark{width:180px;height:115px}#loading p{font-size:11px;letter-spacing:3px;margin-top:28px}#loading small{font-size:11px;color:#7f95a5}
.error-panel{max-width:520px;padding:0 24px;text-align:center;line-height:1.7}.error-panel h2{font-weight:400;font-size:24px;color:#dcc092;margin:0 0 10px}.error-panel p{font-size:13px;letter-spacing:0;color:#c8c3ba;margin:6px 0}
.noscript{position:fixed;inset:0;z-index:60;margin:0;display:flex;align-items:center;justify-content:center;background:#0b0a06;color:#eee}
@keyframes rotate{to{transform:rotate(360deg)}}@keyframes pulse{50%{box-shadow:0 0 14px #ceaa6a55}}@keyframes fall{0%{transform:translateY(-30px) rotateY(0);opacity:0}10%{opacity:1}100%{transform:translateY(100vh) rotateY(900deg);opacity:0}}
@media(min-width:1600px){.intro{width:300px}.session{width:200px}}
@media(max-height:820px) and (min-width:1000px){.intro{top:4%}h1{font-size:46px;margin:12px 0}.edition{margin:14px 0}.feature-list button{padding:10px 0}.tagline{font-size:14px}.session{top:8%}}
@media(max-width:1250px){.intro{width:205px}.session{right:3%;width:150px}.console{gap:2.4%;padding:18px 3%}.bet,.last{padding-left:2.4%}.credit{min-width:135px}.bet{min-width:150px}.spin{width:140px}.utility{display:none}.secondary{width:60px}h1{font-size:44px}}
@media(max-width:1000px){.intro,.session{display:none}#viewHint{display:none}}
@media(max-width:850px){header{height:72px;padding:0 5%}.arcade,.pill{display:none}.top-right{gap:8px}.icon{width:32px;height:32px;font-size:16px}.brand{font-size:12px;gap:8px}.brandmark{width:28px;height:28px}
#scene{top:72px;bottom:200px}main{top:72px;bottom:200px}#viewbar{top:82px}.view-btn{font-size:11px;padding:7px 12px}
.console{min-height:200px;display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px 10px;padding:14px 5%}.credit,.bet,.last{min-width:0}.bet,.last{padding-left:12px}.console strong{font-size:22px}.console small{display:none}.console label{font-size:9px;letter-spacing:.8px;margin-bottom:7px}
.stepper{gap:8px}.stepper strong{font-size:19px;min-width:30px}.stepper button{width:28px;height:28px}.last{text-align:right}.gamble-btn{margin-left:auto;font-size:9px}
.actions{grid-column:1/4;grid-row:2;margin:0;width:100%}#maxBet{display:none}.spin{flex:1;height:52px;font-size:13px;gap:14px}.secondary{height:52px;width:64px;flex-shrink:0}
.utility{display:flex;flex-direction:row;grid-column:1/4;grid-row:3;justify-content:space-between;gap:8px}.utility button{font-size:9px}
#featureBar{bottom:206px;left:10px;right:10px;transform:none;max-width:none;flex-wrap:wrap;gap:8px 12px;padding:10px 12px}.fb-head{min-width:0;flex:1 1 150px;gap:2px}.fb-head .eyebrow{font-size:9px}.fb-head strong{font-size:17px}#fbBody{gap:5px}.pick{width:31px;height:34px;font-size:12px}.bar-cta{padding:11px 14px}
#toast{bottom:auto;top:150px}.vignette{background:radial-gradient(ellipse at 50% 45%,transparent 55%,#0b0a0699)}.machine-caption{left:5%;width:90%;font-size:10px}dialog{padding:18px}.lab-options{grid-template-columns:1fr}.lab-options button{padding:14px}.rule-grid{grid-template-columns:repeat(4,1fr)}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important}}

body.close-view .machine-caption{opacity:0}body.feature-on #toast{bottom:250px}
.pick.capsule{border-radius:10px;background:linear-gradient(180deg,#403215,#1a1408);border-color:#ceaa6a99;color:#f2e8d6}.pick.capsule.picked{background:#ceaa6a;color:#191308}
.twins-table td{vertical-align:middle}.swatch{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:8px}
.ab{display:inline-flex;gap:10px}.ab .cta{min-width:130px}
.coin.inf{background:none;border:0;box-shadow:none;width:auto;height:auto;font-size:26px;color:#d8b986;text-shadow:0 0 12px #ceaa6a}
.live-src{font-size:10px;letter-spacing:1px;color:#e0c99e;margin-top:6px}
@media(max-width:850px){body.feature-on #toast{bottom:auto;top:150px}}
h1{font-size:clamp(34px,3.6vw,56px);margin:16px 0}.edition{margin:16px 0 18px}.intro .feature-list button{padding:10px 0}.tagline{margin:10px 0}
@media(max-height:820px) and (min-width:1000px){.intro .feature-list button{padding:7px 0}.feature-list small{margin-top:3px}h1{font-size:42px;margin:8px 0}}

/* ---- bonus scenes and fullscreen ---- */
.bar-cta{min-height:44px}.bar-ghost{border:1px solid #816d4485;padding:11px 14px;border-radius:6px;font-size:12px;color:#d9cfba;min-height:44px;letter-spacing:.5px}
.pick{min-width:44px;min-height:44px}
@media(max-width:850px){.pick{width:44px;height:44px}}
#fs{position:fixed;inset:0;z-index:30;background:#060402;display:flex;flex-direction:column}#fs[hidden]{display:none}
#fsStage{flex:1 1 auto;min-height:0;display:flex;align-items:center;justify-content:center;padding:env(safe-area-inset-top) env(safe-area-inset-right) 0 env(safe-area-inset-left);overflow:hidden}
#fsCanvas{display:block;touch-action:manipulation;cursor:pointer;border-radius:6px;box-shadow:0 0 60px #c9a46a22}
#fsBar{flex:none;background:#12100a;border-top:1px solid #ceaa6a55;padding:8px max(10px,env(safe-area-inset-right)) calc(8px + env(safe-area-inset-bottom)) max(10px,env(safe-area-inset-left));display:flex;flex-wrap:wrap;gap:6px;align-items:stretch}
.fsrow{display:flex;gap:6px;align-items:stretch;min-width:0}.fsgroup{display:flex;gap:6px;align-items:stretch}.fssound{display:flex;gap:6px;align-items:center}
.fsb{min-height:48px;min-width:58px;padding:4px 8px;border:1px solid #8e7a5260;border-radius:6px;background:#1c160b;color:#f3ebdb;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;flex:0 0 auto}
.fsb b{font:700 11px Georgia,serif;letter-spacing:.7px;white-space:nowrap}.fsb small{font-size:10px;color:#b4ab96;letter-spacing:.2px;white-space:nowrap}
.fsb[aria-pressed=true]{border-color:#ceaa6a;background:#ceaa6a22}.fsb[hidden],.fsgroup[hidden],.fs-go[hidden]{display:none}
.fs-spin,.fs-go{min-width:132px;min-height:56px;background:linear-gradient(120deg,#e0c79e,#c29541);color:#191308;box-shadow:0 3px 0 #695122;border-color:#fff3d0}.fs-spin b,.fs-go b{font-size:17px;letter-spacing:1.6px;color:#191308}.fs-spin small,.fs-go small{color:#3a2c12;font-size:11px}
.fs-go{background:linear-gradient(120deg,#ffe9b0,#e0a640);animation:pulse 1.4s ease-in-out infinite}
.fs-g{background:#352911;border-color:#c8a056}.fs-g b{color:#f2e8d6}
.fs-exit{margin-left:auto}.fs-test{border-style:dashed;border-color:#7ff3ff80}
.fsbet,.fsbal{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:0 10px;min-width:62px;border:1px solid #ffffff12;border-radius:6px}
.fsbet small,.fsbal small{font-size:9px;letter-spacing:1px;color:#bab19d}.fsbet b,.fsbal b{font:400 20px Georgia,serif;font-variant-numeric:tabular-nums;color:#f3e7c9}.fsbal b{color:#ffe9b0}
#fs_vol{width:70px;accent-color:#ceaa6a;min-height:44px}
.fsb:disabled{opacity:.4}
@media(min-width:900px){.fsrow{display:contents}}
@media(max-width:899px){#fsBar{flex-direction:column;gap:6px;max-height:55vh;overflow-y:auto}.fsrow{flex-wrap:wrap}.fs-exit{margin-left:0}.fsb{min-height:48px;min-width:0;flex:1 1 calc(25% - 6px)}.fsmain .fs-spin,.fsmain .fs-go{flex:1 1 calc(50% - 6px)}.fsgroup{flex:1 1 100%}.fsgroup .fsb{flex:1 1 0}.fsbet{flex:1.2 1 0}.fsbal{flex:1 1 100%;flex-direction:row;gap:10px;min-height:40px}.fssound{flex:1 1 calc(50% - 6px)}.fssound .fsb{flex:1 1 auto}#fs_vol{flex:1;min-width:40px;width:auto}}
body.fs-on #featureBar{position:static;transform:none;margin:6px auto 8px;width:min(96vw,1100px);max-width:none;bottom:auto;z-index:auto;box-shadow:none;flex:none;padding:8px 12px;gap:10px 14px}
body.fs-on #toast{z-index:70;top:auto;bottom:calc(var(--fsbar-h,130px) + 16px)}body.fs-on #celebration{z-index:60}
body.fs-on .fb-head strong{font-size:18px}

/* ---------- Bonus preview ---------- */
.pv-banner { padding: 10px 14px; border: 1px solid #d9a441; border-radius: 10px; background: rgba(217,164,65,.14); color: #f3e7c9; margin: 0 0 8px; }
.pv-list { display: grid; gap: 10px; margin: 12px 0 6px; }
.pv-btn { display: grid; gap: 3px; text-align: left; min-height: 56px; padding: 11px 16px; border-radius: 12px; border: 1px solid rgba(201,164,106,.6); background: rgba(201,164,106,.1); color: #f3e7c9; cursor: pointer; font: inherit; }
.pv-btn b { font-size: 16px; letter-spacing: .02em; }
.pv-btn small { color: #cdbb95; font-size: 13px; line-height: 1.3; }
.pv-btn:hover, .pv-btn:focus-visible { background: rgba(201,164,106,.24); outline: 2px solid #c9a46a; outline-offset: 2px; }
.pv-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; margin: 8px 0; color: #e6d9bb; }
.pv-chip { min-height: 44px; min-width: 56px; padding: 8px 14px; border-radius: 999px; border: 1px solid rgba(201,164,106,.6); background: transparent; color: #f3e7c9; cursor: pointer; font: inherit; }
.pv-chip.on { background: #c9a46a; color: #1b1206; font-weight: 700; }
.pv-start, .pv-exit { min-height: 48px; margin-top: 12px; width: 100%; }
body.practice .fsbal b, body.practice #fsBal { color: #ffd37a; }
#fs_test[aria-pressed="true"] { outline: 2px solid #d9a441; background: rgba(217,164,65,.22); }
#modal #close { min-width: 44px; min-height: 44px; }
body.practice .credit::before { content: "PRACTICE CHIPS · NOT REAL LAYR"; display: block; color: #d9a441; font-size: 11px; font-weight: 700; letter-spacing: .12em; margin-bottom: 4px; }
body.practice .credit strong { color: #ffd37a; }
